#!/usr/bin/env bash
# Table test for scripts/ci/sanitize-issue-text.py (#4747 review round 2).
#
# The RED case on the pre-fix head: an HTML comment whose opener or closer is
# split by a zero-width character. The old order stripped format characters
# AFTER the comment regex, so the regex saw no comment, the strip then
# produced a well-formed one, and the hidden text reached the model.
#
# Fixture JSON is generated by python3 so \u escapes become real characters
# and this file carries no literal invisible bytes.
set -euo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT="$(cd "${HERE}/../.." && pwd)"
SANITIZER="${ROOT}/scripts/ci/sanitize-issue-text.py"

SCRATCH="$(mktemp -d "${TMPDIR:-/tmp}/sanitize-issue.XXXXXX")"
trap 'rm -rf "${SCRATCH}"' EXIT

fail=0

# write_case <tag> <python body expression>
write_case() {
  python3 - "$1" "${SCRATCH}/$1.json" <<'PY'
import json, sys
tag, path = sys.argv[1], sys.argv[2]
bodies = {
    # Opener split by U+200B and closer split by U+200B. After stripping the
    # format chars first this is a well-formed comment and must be removed.
    "split": "visible text <!" + "\u200b" + "-- hidden instruction -" + "\u200b" + "-> tail text",
    # Unclosed opener: everything after it is treated as comment content.
    "unclosed": "keep this <!" + "-" + "-" + " rest is hidden payload",
    # Abrupt HTML close: two hyphens, bang, gt. Browsers accept it.
    "abrupt": "head <!" + "-" + "-" + " x " + "-" + "-" + "!>" + " foot",
    # Bidi override U+202E mid-word must be removed.
    "bidi": "abc\u202edef",
    # A supplementary-plane variation selector (Mn, U+E0101) hidden in text.
    "vselect": "plain \U000e0101 text",
    # Link reference definitions are invisible in rendered markdown.
    "linkref": "real line\n[//]: # (https://tracker.invalid/x)\nnext line",
    # Clean control: must pass byte-identical.
    "clean": "Plain issue body with a normal link https://github.com/a/b and @someone mention.",
}
print(json.dumps({"title": "T " + tag, "body": bodies[tag]}))
json.dump({"title": "T " + tag, "body": bodies[tag]}, open(path, "w"))
PY
}

# run_case <tag> -> sanitized text on stdout via file
run_case() {
  write_case "$1"
  python3 "${SANITIZER}" "${SCRATCH}/$1.json" "${SCRATCH}/$1.md" || {
    echo "FAIL[$1]: sanitizer exited nonzero"; fail=1; return 1
  }
  return 0
}

has() { grep -qF "$2" "${SCRATCH}/$1.md"; }
lacks() { ! grep -qF "$2" "${SCRATCH}/$1.md"; }

# 1. Split-close comment: hidden text must be gone, visible text kept.
if run_case split; then
  if lacks split "hidden instruction" && has split "visible text" && has split "tail text" && has split "html comment removed"; then
    echo "PASS: zero-width-split HTML comment removed"
  else
    echo "FAIL[split]: injected text survived:"; cat "${SCRATCH}/split.md"; fail=1
  fi
fi

# 2. Unclosed opener: text after the opener must not reach the output.
if run_case unclosed; then
  if lacks unclosed "rest is hidden payload" && has unclosed "keep this"; then
    echo "PASS: unclosed comment opener truncated to end"
  else
    echo "FAIL[unclosed]: content after an unclosed opener survived:"; cat "${SCRATCH}/unclosed.md"; fail=1
  fi
fi

# 3. Abrupt close must be treated as a real close.
if run_case abrupt; then
  if lacks abrupt " x " && has abrupt "head" && has abrupt "foot"; then
    echo "PASS: abrupt comment close removed"
  else
    echo "FAIL[abrupt]: comment survived the abrupt close:"; cat "${SCRATCH}/abrupt.md"; fail=1
  fi
fi

# 4. Bidi override removed (regression lock: worked before, must keep working).
if run_case bidi; then
  if has bidi "abcdef"; then
    echo "PASS: bidi override stripped"
  else
    echo "FAIL[bidi]: bidi char survived:"; cat "${SCRATCH}/bidi.md"; fail=1
  fi
fi

# 5. Supplementary variation selector removed (review nit fix).
if run_case vselect; then
  if has vselect "plain  text"; then
    echo "PASS: variation selector stripped"
  else
    echo "FAIL[vselect]: selector survived:"; cat "${SCRATCH}/vselect.md"; fail=1
  fi
fi

# 6. Link reference definition removed (review nit fix).
if run_case linkref; then
  if lacks linkref "tracker.invalid" && has linkref "real line" && has linkref "next line"; then
    echo "PASS: link reference definition stripped"
  else
    echo "FAIL[linkref]: hidden link target survived:"; cat "${SCRATCH}/linkref.md"; fail=1
  fi
fi

# 7. Clean input passes unchanged (title + body intact).
if run_case clean; then
  if has clean "# T clean" && has clean "Plain issue body with a normal link https://github.com/a/b and @someone mention."; then
    echo "PASS: clean issue unchanged"
  else
    echo "FAIL[clean]: clean text was altered:"; cat "${SCRATCH}/clean.md"; fail=1
  fi
fi

exit "${fail}"
